package ru.truetv.launcher;
import java.util.*;
public final class AccessibilitySettingsCheck {
 static int checks;static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}interface Task {void run()throws Exception;}static void reject(Task task)throws Exception {try{task.run();throw new AssertionError("Unexpected success");}catch(java.io.IOException|IllegalArgumentException good){checks++;}}
 static final String FIRST="org.test.first/org.test.first.Service",SECOND="org.test.second/org.test.second.Service";
 static final class Store implements RestrictedOps.Runner {String services=FIRST,enabled="1";List<String> calls=new ArrayList<>();boolean refuse,ignore;public ShellReply run(String c){calls.add(c);if(c.contains(" get secure enabled_accessibility_services"))return new ShellReply(0,services);if(c.contains(" get secure accessibility_enabled"))return new ShellReply(0,enabled);if(refuse)return new ShellReply(1,"Permission denied");if(c.contains(" put secure enabled_accessibility_services ")){if(!ignore)services=c.substring(c.indexOf('\'')+1,c.lastIndexOf('\''));}else if(c.contains(" put secure accessibility_enabled ")){if(!ignore)enabled=c.endsWith(" 1")?"1":"0";}else throw new AssertionError("Unexpected command "+c);return new ShellReply(0,"");}}
 static final class HomeStore implements RestrictedOps.Runner {
  final String stock="com.google.android.tvlauncher",home=stock+"/.MainActivity";List<String> calls=new ArrayList<>();boolean disabled,ignoreFreeze,failSwitch,missingOwn,failRestore;String restored;
  public ShellReply run(String cmd){calls.add(cmd);if(cmd.contains("resolve-activity")){if(cmd.endsWith(" -p ru.truetv.launcher"))return new ShellReply(0,missingOwn?"No activity found":"ru.truetv.launcher/.HomeActivity");return new ShellReply(0,!disabled?"priority=2 preferredOrder=0\n"+home:failSwitch?"other.home/.Main":"ru.truetv.launcher/.HomeActivity");}if(cmd.contains("set-home-activity"))return new ShellReply(0,"Success");if(cmd.startsWith("pm disable-user")){if(!ignoreFreeze)disabled=true;return new ShellReply(0,"");}if(cmd.startsWith("pm default-state")||cmd.startsWith("pm enable")){if(failRestore)return new ShellReply(1,"denied");disabled=false;restored=cmd;return new ShellReply(0,"");}if(cmd.startsWith("pm list packages -d"))return new ShellReply(0,disabled?"package:"+stock:"");if(cmd.startsWith("pm list packages -e"))return new ShellReply(0,disabled?"":"package:"+stock);throw new AssertionError("Unexpected handoff command "+cmd);}
 }
 public static void main(String[] args)throws Exception {
  check(AccessibilitySettings.component("org.test.first/.Service").equals(FIRST),"short component normalizes");check(AccessibilitySettings.parse("null").isEmpty(),"unset list empty");check(AccessibilitySettings.parse(FIRST+":"+FIRST).size()==1,"duplicates canonicalized");
  for(String value:new String[]{"org.test.first/.Bad;reboot","org.test.first/..Bad","org.test.first/.Bad Name","no-component","org.test.first/Bad'","org.test.first/Service:"})reject(()->AccessibilitySettings.component(value));
  reject(()->AccessibilitySettings.parse(FIRST+":garbage"));reject(()->AccessibilitySettings.read(-1,"accessibility_enabled"));reject(()->AccessibilitySettings.read(0,"unrelated"));
  Store store=new Store();AccessibilitySettings.enable(store,Arrays.asList(SECOND),0);check(AccessibilitySettings.parse(store.services).equals(new LinkedHashSet<>(Arrays.asList(FIRST,SECOND))),"preserves existing service and adds only selected");check(store.calls.stream().noneMatch(c->c.endsWith("put secure accessibility_enabled 1")),"already-on switch not rewritten");
  store=new Store();store.services="null";store.enabled="0";AccessibilitySettings.enable(store,Arrays.asList(SECOND),10);check(store.services.equals(SECOND)&&store.enabled.equals("1"),"fresh user activation verified");check(store.calls.stream().allMatch(c->c.contains("--user 10 ")),"only selected user commands");
  store=new Store();AccessibilitySettings.enable(store,Arrays.asList(FIRST),0);check(store.calls.stream().noneMatch(c->c.contains(" put ")),"already enabled is read-only");
  Store denied=new Store();denied.refuse=true;reject(()->AccessibilitySettings.enable(denied,Arrays.asList(SECOND),0));check(denied.services.equals(FIRST),"denial preserves original");Store ignored=new Store();ignored.ignore=true;reject(()->AccessibilitySettings.enable(ignored,Arrays.asList(SECOND),0));
  reject(()->AccessibilitySettings.enable(new Store(),Collections.emptyList(),0));
  int[] calls={0};reject(()->AccessibilitySettings.enable(cmd->{calls[0]++;return new ShellReply(0,cmd.contains("get secure accessibility_enabled")?"1":calls[0]>=3?SECOND:FIRST);},Arrays.asList(FIRST),0));check(calls[0]==3,"concurrent settings change stops before writing");
  Store off=new Store();off.services=FIRST+":"+SECOND;AccessibilitySettings.disable(off,Arrays.asList(SECOND),0);check(off.services.equals(FIRST)&&off.enabled.equals("1"),"disable preserves other service and global switch");off=new Store();AccessibilitySettings.disable(off,Arrays.asList(FIRST),0);check(off.services.isEmpty()&&off.enabled.equals("0"),"disable last service turns switch off");Store absent=new Store();AccessibilitySettings.disable(absent,Arrays.asList(SECOND),0);check(absent.calls.stream().noneMatch(c->c.contains(" put ")),"disabling absent service is read-only");
  check(HomeDefaults.isOwn("priority=0\nru.truetv.launcher/.HomeActivity"),"exact Home readback");check(!HomeDefaults.isOwn("ru.truetv.launcher/.HomeActivityX"),"Home prefix rejected");check(!HomeDefaults.isOwn("other.app/.Home\nru.truetv.launcher/.HomeActivity"),"ambiguous resolver rejected");
  List<String> home=new ArrayList<>();HomeDefaults.assign(cmd->{home.add(cmd);return new ShellReply(0,home.size()<3?"other.app/.Home":"ru.truetv.launcher/ru.truetv.launcher.HomeActivity");},0,28);check(home.size()==3&&home.get(1).equals("cmd package set-home-activity --user 0 ru.truetv.launcher/ru.truetv.launcher.HomeActivity"),"Home mutation plus confirmed readback");
  reject(()->HomeDefaults.assign(cmd->new ShellReply(0,"other.app/.Home"),0,28));reject(()->HomeDefaults.assign(cmd->new ShellReply(1,"denied"),0,28));
  List<String> modern=new ArrayList<>();HomeDefaults.assign(cmd->{modern.add(cmd);if(cmd.startsWith("cmd role get-role-holders"))return new ShellReply(0,"ru.truetv.launcher");return new ShellReply(0,modern.size()<3?"other.app/.Home":"ru.truetv.launcher/.HomeActivity");},0,34);check(modern.size()==4&&modern.get(1).equals("cmd role add-role-holder --user 0 android.app.role.HOME ru.truetv.launcher 1"),"modern Home uses package role and verifies holder");reject(()->HomeDefaults.assign(cmd->{throw new AssertionError("must not execute unsupported shell command");},0,21));
  String stock="priority=2 preferredOrder=0 match=0x108000 specificIndex=-1 isDefault=true\ncom.google.android.tvlauncher/.MainActivity\n";
  try{HomeDefaults.assign(cmd->new ShellReply(0,cmd.contains("set-home-activity")?"Success":stock),0,28);throw new AssertionError("Stock Home must not be reported assigned");}catch(HomeDefaults.NotAssigned e){check(e.resolved.equals("com.google.android.tvlauncher/.MainActivity")&&e.priority==2,"owner resolver output identifies stock Home and priority2");check(e.priorityOverridesPreference(28)&&!e.priorityOverridesPreference(34),"priority explanation scoped to pre-role Android");}
  HomeDefaults.NotAssigned normal=new HomeDefaults.NotAssigned("priority=0 preferredOrder=0\nother.app/.Home");check(!normal.priorityOverridesPreference(28),"ordinary assignment failure is not blamed on system priority");
  HomeDefaults.NotAssigned malformed=new HomeDefaults.NotAssigned("Error: permission denied");check(malformed.resolved==null&&!malformed.priorityOverridesPreference(28),"permission error cannot look like a confirmed stock Home");
  HomeStore freeze=new HomeStore();HomeDefaults.freezeCurrent(freeze,freeze.stock,0,28,0);check(freeze.disabled&&freeze.restored==null,"priority2 deadlock allows explicit selected-stock freeze and verified own Home");check(freeze.calls.stream().noneMatch(c->c.contains("uninstall")||c.contains("root")||c.contains("remount")),"handoff never deletes packages or changes root/partitions");
  HomeStore unavailable=new HomeStore();unavailable.missingOwn=true;reject(()->HomeDefaults.freezeCurrent(unavailable,unavailable.stock,0,28,0));check(!unavailable.disabled&&unavailable.calls.stream().noneMatch(c->c.startsWith("pm disable")),"missing own Home aborts before freezing stock");
  HomeStore rollback=new HomeStore();rollback.failSwitch=true;reject(()->HomeDefaults.freezeCurrent(rollback,rollback.stock,0,28,0));check(!rollback.disabled&&rollback.restored.equals("pm default-state --user 0 "+rollback.stock),"failed switch restores original default enabled state");
  HomeStore explicit=new HomeStore();explicit.failSwitch=true;reject(()->HomeDefaults.freezeCurrent(explicit,explicit.stock,10,28,1));check(!explicit.disabled&&explicit.restored.equals("pm enable --user 10 "+explicit.stock),"rollback preserves explicit enabled state and chosen user");
  HomeStore refused=new HomeStore();refused.ignoreFreeze=true;reject(()->HomeDefaults.freezeCurrent(refused,refused.stock,0,28,0));check(!refused.disabled&&refused.restored!=null,"silently ignored disable is detected and stock is restored");
  HomeStore deniedRollback=new HomeStore();deniedRollback.failSwitch=true;deniedRollback.failRestore=true;try{HomeDefaults.freezeCurrent(deniedRollback,deniedRollback.stock,0,28,0);throw new AssertionError("Must fail");}catch(java.io.IOException e){check(e.getMessage().contains("restoration also needs attention"),"rollback failure is explicit, never reported restored");}
  reject(()->HomeDefaults.freezeCurrent(new HomeStore(),"ru.truetv.launcher",0,28,0));reject(()->HomeDefaults.freezeCurrent(new HomeStore(),"android",0,28,0));reject(()->HomeDefaults.freezeCurrent(new HomeStore(),freeze.stock,0,21,0));reject(()->HomeDefaults.freezeCurrent(new HomeStore(),freeze.stock,0,28,3));
  System.out.println("PASS "+checks+" explicit Accessibility activation / Home default checks");
 }
}
